/**
 * Progress Bar Module for Noodl
 */
(() => {
    const React = window.React;
    
    /**
     * Progress Bar React Component
     */
    function ProgressBarComponent(props) {
        const {
            style,
            className,
            startStep,
            endStep,
            currentStep,
            bgColor,
            progressColor,
            borderRadius,
            animationDuration
        } = props;
        
        // Calculate progress percentage
        const calculateProgress = React.useCallback(() => {
            const totalSteps = endStep - startStep;
            const currentPosition = Math.max(0, Math.min(currentStep - startStep, totalSteps));
            return (totalSteps > 0) ? (currentPosition / totalSteps * 100) : 0;
        }, [startStep, endStep, currentStep]);
        
        const progressPercentage = calculateProgress();
        
        // Notify parent component about progress changes
        React.useEffect(() => {
            if (props.onProgressChange) {
                props.onProgressChange(progressPercentage);
            }
        }, [progressPercentage, props.onProgressChange]);
        
        // Container styles
        const containerStyle = {
            position: 'relative',
            overflow: 'hidden',
            width: '100%',
            height: '100%',
            backgroundColor: bgColor,
            borderRadius: `${borderRadius}px`,
            ...style
        };
        
        // Progress bar styles
        const progressStyle = {
            position: 'absolute',
            top: 0,
            left: 0,
            height: '100%',
            width: `${progressPercentage}%`,
            backgroundColor: progressColor,
            borderRadius: `${borderRadius}px 0 0 ${borderRadius}px`,
            transition: `width ${animationDuration}s ease-in-out`
        };
        
        return React.createElement(
            'div',
            { 
                style: containerStyle,
                className: className
            },
            React.createElement('div', { style: progressStyle })
        );
    }
    
    /**
     * Progress Bar Node Definition
     */
    const ProgressBarNode = {
        name: 'noodl.controls.progressbar',
        displayName: 'Progress Bar',
        category: 'Visual',
        color: 'component',
        
        initialize() {
            this.lastProgress = 0;
            
            this.props = {
                startStep: 0,
                endStep: 100,
                currentStep: 0,
                bgColor: '#E0E0E0',
                progressColor: '#4CAF50',
                borderRadius: 4,
                animationDuration: 0.5,
                onProgressChange: this.onProgressChange.bind(this)
            };
            
            // Initialize style for component
            this._style = {};
            
            // Function to update component styles
            this.setStyle = (style) => {
                Object.assign(this._style, style);
                this.forceUpdate();
            };
        },
        
        getReactComponent() {
            return ProgressBarComponent;
        },
        
        inputs: {
            startStep: {
                index: 1,
                type: 'number',
                displayName: 'Start Step',
                group: 'Steps',
                default: 0,
                set(value) {
                    this.props.startStep = value;
                    this.calculateAndUpdateProgress();
                }
            },
            endStep: {
                index: 2,
                type: 'number',
                displayName: 'End Step',
                group: 'Steps',
                default: 100,
                set(value) {
                    this.props.endStep = value;
                    this.calculateAndUpdateProgress();
                }
            },
            currentStep: {
                index: 3,
                type: 'number',
                displayName: 'Current Step',
                group: 'Steps',
                default: 0,
                set(value) {
                    this.props.currentStep = value;
                    this.calculateAndUpdateProgress();
                }
            },
            bgColor: {
                index: 4,
                type: 'color',
                displayName: 'Background Color',
                group: 'Style',
                default: '#E0E0E0',
                set(value) {
                    this.props.bgColor = value;
                    this.forceUpdate();
                }
            },
            progressColor: {
                index: 5,
                type: 'color',
                displayName: 'Progress Color',
                group: 'Style',
                default: '#4CAF50',
                set(value) {
                    this.props.progressColor = value;
                    this.forceUpdate();
                }
            },
            borderRadius: {
                index: 6,
                type: 'number',
                displayName: 'Border Radius',
                group: 'Style',
                default: 4,
                set(value) {
                    this.props.borderRadius = value;
                    this.forceUpdate();
                }
            },
            animationDuration: {
                index: 7,
                type: 'number',
                displayName: 'Animation Duration (s)',
                group: 'Animation',
                default: 0.5,
                set(value) {
                    this.props.animationDuration = value;
                    this.forceUpdate();
                }
            },
            reset: {
                index: 8,
                type: 'signal',
                displayName: 'Reset',
                group: 'Control',
                set() {
                    this.props.currentStep = this.props.startStep;
                    this.calculateAndUpdateProgress();
                }
            }
        },
        
        outputs: {
            progress: {
                type: 'number',
                displayName: 'Progress (%)',
                group: 'Output'
            },
            completed: {
                type: 'signal',
                displayName: 'Completed',
                group: 'Output'
            }
        },
        
        methods: {
            calculateProgress() {
                const totalSteps = this.props.endStep - this.props.startStep;
                const currentPosition = Math.max(0, Math.min(this.props.currentStep - this.props.startStep, totalSteps));
                return (totalSteps > 0) ? (currentPosition / totalSteps * 100) : 0;
            },
            
            calculateAndUpdateProgress() {
                const progress = this.calculateProgress();
                
                // Directly update the progress output
                this.setOutputs({
                    progress: progress
                });
                
                // Check for completion
                if (progress >= 100 && this.lastProgress < 100) {
                    this.sendSignalOnOutput('completed');
                }
                
                // Update last progress value
                this.lastProgress = progress;
                
                // Force update to refresh UI
                this.forceUpdate();
            },
            
            onProgressChange(progress) {
                // This callback is triggered from the React component
                // We use it to update outputs directly
                this.setOutputs({
                    progress: progress
                });
                
                // Check for completion
                if (progress >= 100 && this.lastProgress < 100) {
                    this.sendSignalOnOutput('completed');
                }
                
                // Update last progress value
                this.lastProgress = progress;
            }
        }
    };
    
    // Register the node with Noodl
    const nodeDefinition = Noodl.defineReactNode(ProgressBarNode);
    
    // Define the module
    Noodl.defineModule({
        reactNodes: [nodeDefinition],
        setup() {
            console.log('Progress Bar Module Loaded');
        }
    });
})();